<script setup>
import {ref,onMounted} from 'vue';import AppShell from '../components/AppShell.vue';import {supabase} from '../services/supabase';import {RouterLink} from 'vue-router';const jobs=ref([]),loading=ref(true);onMounted(async()=>{const {data:{user}}=await supabase.auth.getUser();const {data}=await supabase.from('saved_jobs').select('job:jobs(*)').eq('student_id',user.id).order('created_at',{ascending:false});jobs.value=(data||[]).map(x=>x.job).filter(Boolean);loading.value=false});async function remove(job){const {data:{user}}=await supabase.auth.getUser();await supabase.from('saved_jobs').delete().eq('student_id',user.id).eq('job_id',job.id);jobs.value=jobs.value.filter(j=>j.id!==job.id)}
</script>
<template><AppShell title="Saved jobs" subtitle="Keep interesting opportunities close"><template #default><span class="eyebrow">YOUR SHORTLIST</span><h1 class="page-title">Saved jobs</h1><p class="page-subtitle">The opportunities you've bookmarked for later.</p><div v-if="loading" class="empty">Loading saved jobs…</div><div v-else-if="jobs.length" class="grid grid-3" style="margin-top:22px"><article v-for="j in jobs" :key="j.id" class="card job-card"><span class="badge green">{{j.job_type}}</span><h3>{{j.title}}</h3><p>{{j.location}} · {{j.category}}</p><div class="job-card-foot"><RouterLink :to="`/jobs/${j.id}`" class="btn btn-primary">View job</RouterLink><button class="btn btn-outline" @click="remove(j)">Remove</button></div></article></div><div v-else class="empty"><h3>No saved jobs yet</h3><p>Save opportunities you're interested in and come back to them anytime.</p><RouterLink to="/jobs" class="btn btn-primary">Find jobs</RouterLink></div></template></AppShell></template>
